-- Generated localized release notes.
local _, namespace = ...
namespace.releaseNotesByLocale = {["deDE"]={["sections"]={{["items"]={"In Tooltips zusammengefasster Punkte werden Spieler, die bekanntermaßen derselben Gruppe angehören, mit einem abgerundeten weißen Rahmen und einem Gruppensymbol gekennzeichnet. Das Gruppensymbol bleibt auch bei Spielern sichtbar, deren Gruppenmitglieder außerhalb der Zusammenfassung liegen.","Die QT-Schaltfläche auf der Weltkarte bleibt vollständig sichtbar und zeigt ein rotes X, wenn QT-Markierungen ausgeblendet sind.","Beim Überfahren der QT-Schaltfläche wird die Karte nicht mehr abgedunkelt, solange QT-Markierungen ausgeblendet sind."},["title"]="Spieler auf Karten"}},["version"]="7.3.1",["welcome"]="Übersichtlichere Gruppeninformationen und Kartensteuerung."},["esES"]={["sections"]={{["items"]={"Las descripciones de los marcadores agrupados reúnen a los jugadores que pertenecen al mismo grupo conocido dentro de un borde blanco redondeado, con un icono de grupo. Los jugadores cuyos compañeros quedan fuera de ese conjunto de marcadores también muestran el indicador de grupo.","El botón QT del mapa del mundo permanece completamente visible y muestra una X roja cuando los marcadores de QT están ocultos.","Pasar el cursor sobre el botón QT ya no atenúa el mapa mientras los marcadores de QT están ocultos."},["title"]="Jugadores en los mapas"}},["version"]="7.3.1",["welcome"]="Información de grupo y controles del mapa más claros."},["esMX"]={["sections"]={{["items"]={"Las descripciones de los marcadores agrupados reúnen a los jugadores que pertenecen al mismo grupo conocido dentro de un borde blanco redondeado, con un ícono de grupo. Los jugadores cuyos compañeros quedan fuera de ese conjunto de marcadores también muestran el indicador de grupo.","El botón QT del mapa del mundo permanece completamente visible y muestra una X roja cuando los marcadores de QT están ocultos.","Pasar el cursor sobre el botón QT ya no atenúa el mapa mientras los marcadores de QT están ocultos."},["title"]="Jugadores en los mapas"}},["version"]="7.3.1",["welcome"]="Información de grupo y controles del mapa más claros."},["frFR"]={["sections"]={{["items"]={"Dans les infobulles des marqueurs regroupés, les joueurs appartenant au même groupe connu sont réunis dans un cadre blanc arrondi, avec une icône de groupe. Un joueur dont les coéquipiers se trouvent hors du regroupement conserve cet indicateur.","Le bouton QT de la carte du monde reste entièrement visible et affiche une croix rouge lorsque les marqueurs QT sont masqués.","Survoler le bouton QT n’assombrit plus la carte lorsque les marqueurs QT sont masqués."},["title"]="Joueurs sur les cartes"}},["version"]="7.3.1",["welcome"]="Des informations de groupe et des commandes de carte plus claires."},["itIT"]={["sections"]={{["items"]={"Nei suggerimenti degli indicatori raggruppati, i giocatori che risultano appartenere allo stesso gruppo sono racchiusi in un bordo bianco arrotondato, con un’icona di gruppo. L’indicatore di gruppo compare anche per un giocatore i cui compagni si trovano fuori da quell’insieme di indicatori.","Il pulsante QT sulla mappa del mondo resta completamente visibile e mostra una X rossa quando gli indicatori QT sono nascosti.","Passare il puntatore sul pulsante QT non oscura più la mappa quando gli indicatori QT sono nascosti."},["title"]="Giocatori sulle mappe"}},["version"]="7.3.1",["welcome"]="Informazioni sul gruppo e controlli della mappa più chiari."},["koKR"]={["sections"]={{["items"]={"묶인 표시의 툴팁에서 같은 파티 소속으로 확인된 플레이어를 둥근 흰색 테두리 안에 모아 보여 주고 파티 아이콘을 표시합니다. 파티원이 해당 묶음 밖에 있는 플레이어에게도 파티 아이콘이 표시됩니다.","세계 지도의 QT 버튼은 항상 선명하게 표시되며, QT 표시를 숨기면 빨간색 X가 나타납니다.","QT 표시를 숨긴 상태에서는 QT 버튼에 마우스를 올려도 지도가 어두워지지 않습니다."},["title"]="지도의 플레이어"}},["version"]="7.3.1",["welcome"]="파티 정보와 지도 조작이 더 명확해졌습니다."},["ptBR"]={["sections"]={{["items"]={"Nas dicas dos marcadores agrupados, jogadores que pertencem ao mesmo grupo conhecido aparecem dentro de uma borda branca arredondada, com um ícone de grupo. Jogadores cujos companheiros estão fora desse conjunto de marcadores também exibem o indicador de grupo.","O botão QT no mapa-múndi permanece totalmente visível e exibe um X vermelho quando os marcadores do QT estão ocultos.","Passar o cursor sobre o botão QT não escurece mais o mapa enquanto os marcadores do QT estão ocultos."},["title"]="Jogadores nos mapas"}},["version"]="7.3.1",["welcome"]="Informações de grupo e controles do mapa mais claros."},["ruRU"]={["sections"]={{["items"]={"В подсказках скоплений меток игроки, о которых известно, что они состоят в одной группе, объединены белой рамкой со скруглёнными углами и значком группы. Значок группы отображается и у игрока, чьи товарищи находятся за пределами этого скопления.","Кнопка QT на карте мира остаётся полностью видимой и показывает красный крестик, когда метки QT скрыты.","Наведение на кнопку QT больше не затемняет карту, если метки QT скрыты."},["title"]="Игроки на картах"}},["version"]="7.3.1",["welcome"]="Более понятные сведения о группе и элементы управления картой."},["zhCN"]={["sections"]={{["items"]={"聚合标记的提示框会将已知属于同一队伍的玩家放在白色圆角边框内，并显示队伍图标。即使队友不在当前聚合标记中，该玩家仍会显示队伍标识。","世界地图上的 QT 按钮始终清晰可见，隐藏 QT 标记时会显示红色叉号。","隐藏 QT 标记时，将鼠标悬停在 QT 按钮上不再使地图变暗。"},["title"]="地图上的玩家"}},["version"]="7.3.1",["welcome"]="更清晰的队伍信息和地图控件。"},["zhTW"]={["sections"]={{["items"]={"群聚標記的提示框會將已知屬於同一隊伍的玩家放在白色圓角邊框內，並顯示隊伍圖示。即使隊友不在目前的群聚標記中，該玩家仍會顯示隊伍標示。","世界地圖上的 QT 按鈕始終清晰可見，隱藏 QT 標記時會顯示紅色叉號。","隱藏 QT 標記時，將滑鼠移至 QT 按鈕上不再使地圖變暗。"},["title"]="地圖上的玩家"}},["version"]="7.3.1",["welcome"]="更清楚的隊伍資訊與地圖控制項。"}}
